A (A-star).ejemplo:
def a_star(grafo, inicio, meta, h):
    pq, g_score = [(h(inicio, meta), 0, inicio)], {inicio: 0}
    while pq:
        _, g, u = heapq.heappop(pq)
        if u == meta: return g
        if g > g_score.get(u, float('inf')): continue
        for v, w in grafo[u]:
            if g + w < g_score.get(v, float('inf')):
                g_score[v] = g + w
                heapq.heappush(pq, (g + w + h(v, meta), g + w, v))

