def es_bst_valido(nodo, minimo=float('-inf'), maximo=float('inf')):
    if not nodo:
        return True
    if not (minimo < nodo.val < maximo):
        return False
    return (es_bst_valido(nodo.izq, minimo, nodo.val) and
            es_bst_valido(nodo.der, nodo.val, maximo))

Bubble Sort.ejemplo:
def bubble_sort(arr):
    n = len(arr)
    for i in range(n - 1):
        swapped = False
        for j in range(n - 1 - i):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
        if not swapped: break

Búsqueda binaria.ejemplo:
def lower_bound(arr, target):
    low, high = 0, len(arr)
    while low < high:
        mid = low + (high - low) // 2
        if arr[mid] < target:
            low = mid + 1
        else:
            high = mid
    return low

Búsqueda en anchura (BFS).ejemplo:
from collections import deque
def bfs(grafo, inicio):
    visitados = {inicio}
    cola = deque([(inicio, 0)])
    while cola:
        u, dist = cola.popleft()
        for v in grafo[u]:
            if v not in visitados:
                visitados.add(v)
                cola.append((v, dist + 1))

