def dfs_ciclo_dirigido(u, grafo, estado):
    estado[u] = 1  # En proceso (gris)
    for v in grafo[u]:
        if estado[v] == 1: return True
        if estado[v] == 0 and dfs_ciclo_dirigido(v, grafo, estado):
            return True
    estado[u] = 2  # Completado (negro)
    return False

