Complejidad amortizada.ejemplo:
# Cola con 2 pilas: cada elemento entra en 'in_s', pasa a 'out_s' y sale -> O(1) amortizado
class ColaDosPilas:
    def __init__(self): self.in_s, self.out_s = [], []
    def push(self, x): self.in_s.append(x)
    def pop(self):
        if not self.out_s:
            while self.in_s: self.out_s.append(self.in_s.pop())
        return self.out_s.pop()

